class Solution {
    unordered_set<int> removed;
    vector<TreeNode*> forest;
    TreeNode* dfs(TreeNode* node, bool isRoot) {
        if (!node) return nullptr;
        bool del = removed.count(node->val) != 0;
        if (isRoot && !del) forest.push_back(node);
        node->left = dfs(node->left, del);
        node->right = dfs(node->right, del);
        return del ? nullptr : node;
    }
public:
    vector<TreeNode*> delNodes(TreeNode* root, vector<int>& to_delete) {
        removed.clear(); forest.clear();
        removed.insert(to_delete.begin(), to_delete.end());
        dfs(root, true);
        return forest;
    }
};
